  PERFORM coaching.apply_candidate_exercise_card_v1($card_1_payload${"migrationKey":"747_coaching_uphill_bound_source_995_candidate_materialization","researchVersion":"2026-07-25.6","definition":{"facilityId":1,"legacyExerciseId":995,"slug":"uphill-bound","canonicalName":"Uphill Bound","displayName":"Uphill Bound","aliases":["Hill Bounds","Uphill Bounding"],"description":"On an inspected, dry, stable uphill lane with a declared gentle-to-moderate grade, perform a short sequence of alternating forward bounds. Each contact projects the body uphill with controlled foot placement, hip extension, trunk organisation, and a planned walk-down recovery. This excludes uphill sprinting, jogging, straight-leg bounds, bilateral hops, downhill bounds, weighted bounds, or an unspecified steep grade.","familyKey":"alternating_uphill_bounds","schemaVersion":"2.0.0","cardVersion":2,"status":"review","identityContract":"short_duration_alternating_forward_bounds_on_an_inspected_gentle_to_moderate_uphill_grade_with_declared_contact_count_or_duration_and_walk_down_recovery","confidence":{"content":72,"scoring":58,"media":50},"movementPatterns":["bound","horizontal_projection","land","brace"],"bodyRegions":["foot","ankle","calf","knee","hamstrings","glutes","hip","pelvis","core","spine","shoulder"],"requiredEquipment":["incline_surface","start_finish_cones","safe_run_out"],"optionalEquipment":["grade_meter","video_capture","timer"],"environment":{"surface":"inspected dry stable uphill lane with no holes, loose material, cross-slope, traffic, or unsafe weather; flat controlled start and finish areas","space":"one athlete at a time in the uphill lane; a separated walk-down recovery route with no cross traffic","stationCapacity":1,"inspection":["inspect grade, surface, traction, weather, visibility, lane, finish, and walk-down route","mark start and finish; declare grade, contact count or duration, and walk-down recovery","remove bystanders and prevent downhill jogging through the active lane","confirm footwear, communication, stop signal, and current running/bounding exposure"],"changeRule":"Changing grade, surface, traction, direction, contact sequence, distance, duration, pace, load, recovery route, or purpose requires revalidation."},"population":{"exerciseCardDoesNotClassifyParticipants":true,"readinessIsWorkoutInput":true,"selectionPrerequisites":["controlled level alternating bounds and pain-free tolerance of current hill-running and ankle/calf/tibial loading","safe inspected lane, grade, finish, and walk-down route","current lower-limb, tendon, impact, and session-fatigue budgets fit","understands the bound pattern, route, stop signal, and full recovery rule"],"excludeOrEscalate":["symptom, restriction, unsafe grade, traction, weather, visibility, surface, footwear, lane, finish, recovery route, or communication conflict","pain, giving way, dizziness, neurologic, circulation, breathing, chest, balance, or communication concern","participant requests stop"],"notEstablishedByEvidence":["universal grade, contact count, duration, recovery, impact reduction, readiness threshold, output, or clinical clearance"]},"provenance":{"legacySources":[995],"identityAuthority":"Source 995 plus alternating-bounds-v1 evidence packet. Uphill Bound is a candidate incline delivery of alternating bounds; grade-specific identity, media, and all approvals remain subject to qualified human review.","humanReviewRequired":true,"approvalsCreated":false,"publicationQuarantined":true,"externalPlaybackVerificationPerformed":false},"anatomy":{"primaryMuscles":["gluteus_maximus","hamstrings","quadriceps","soleus","gastrocnemius"],"secondaryMuscles":["gluteus_medius","hip_flexors","intrinsic_foot","obliques","spinal_stabilizers"],"joints":["foot","ankle","knee","hip","pelvis","thoracolumbar_spine","scapulothoracic_articulation","shoulder"],"jointActions":["ankle_plantarflexion","knee_extension","hip_extension","contralateral_hip_flexion","trunk_bracing","landing_flexion_control